(()=>{'use strict';function openTarget(){let id;try{id=decodeURIComponent(location.hash.slice(1))}catch{return}const el=document.getElementById(id);if(el&&el.tagName==='DETAILS'){el.open=true;el.scrollIntoView({block:'start'});}}window.addEventListener('hashchange',openTarget);openTarget();document.querySelectorAll('#s90g-redesign [data-free-entry]').forEach(link=>link.addEventListener('click',()=>{if(typeof window.gtag==='function')window.gtag('event','free_entry_click',{source_page:'servizi',cta_position:'redesign-content',content_type:'free_evaluation'});}));})();